1. What is the output?
class Outer {
    int x = 10;
    class Inner {
        int x = 20;
        void show(int x) {
            System.out.println(x);
            System.out.println(this.x);
            System.out.println(Outer.this.x);
        }
    }
}
new Outer().new Inner().show(30);

