6. What does this print and what inner class concept does it demonstrate?
interface Printer { void print(); }
class Demo {
    String msg = "outer";
    Printer getPrinter() {
        String msg = "local";  // effectively final
        return new Printer() {
            String msg = "inner";
            @Override
            public void print() {
                System.out.println(msg);             // Line 1
                System.out.println(this.msg);        // Line 2
                System.out.println(Demo.this.msg);   // Line 3
            }
        };
    }
    public static void main(String[] args) { new Demo().getPrinter().print(); }
}

