public class Cache {

    // Static nested — Entry is a pure data holder, no outer instance dependency
    public static class Entry {
        private final String key;
        private final Object value;
        private final long   expiryMs;

        public Entry(String key, Object value, long ttlMs) {
            this.key      = key;
            this.value    = value;
            this.expiryMs = System.currentTimeMillis() + ttlMs;
        }

        public boolean isExpired() {
            return System.currentTimeMillis() > expiryMs;
        }

        public Object getValue() { return value; }
        public String getKey()   { return key; }
    }

    private final java.util.Map<String, Entry> store = new java.util.HashMap<>();

    public void put(String key, Object value, long ttlMs) {
        store.put(key, new Entry(key, value, ttlMs));
    }

    public Object get(String key) {
        Entry entry = store.get(key);
        if (entry == null || entry.isExpired()) {
            store.remove(key);
            return null;
        }
        return entry.getValue();
    }
} — Entry is static: it holds data only, no need to access Cache's state. This follows Effective Java Item 24 — static by default when outer instance access is not needed.

